 lines+=['','## 增员考据','', '尹隆河增设慈禧君主位表现朝廷政令，不占战斗站位；依据与史料可证明的范围见[joint_v2/history_notes.md](joint_v2/history_notes.md)。原五名战斗单位保持。','', '## 追踪与经济联合验收','',f'逐关完整轨迹来自`{a.difficulty}`。`chapter_difficulty_report_v2.csv`含胜/局数、95%区间、敌星、等级差与推荐战力；逐单元格改动在`joint_v2/data_changes.csv`。',f"经济联合验收{'通过'if metrics['all_pass']else'尚有未通过项'}，详见economy_report_v2.md。单局难度达标与完整八章的等待、星级、库存均单独检验。"]
 (ROOT/'assets/reports/chapter_difficulty_report_v2.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'economy':metrics['all_pass'],'difficulty':difficulty_pass,'accounts':len(runs),'changes':len(changes)}))
